        $ap${"ask_gpt":{"name":"ask_gpt","displayName":"Ask GPT","description":"Ask ChatGPT anything you want!","requireAuth":true,"props":{"deploymentId":{"displayName":"Deployment Name","description":"The name of your model deployment.","required":true,"type":"SHORT_TEXT"},"prompt":{"displayName":"Question","required":true,"type":"LONG_TEXT"},"temperature":{"displayName":"Temperature","required":false,"description":"Controls randomness: Lowering results in less random completions. As the temperature approaches zero, the model will become deterministic and repetitive.","defaultValue":0.9,"type":"NUMBER"},"maxTokens":{"displayName":"Maximum Tokens","required":true,"description":"The maximum number of tokens to generate. Requests can use up to 2,048 or 4,096 tokens shared between prompt and completion depending on the model. Don't set the value to maximum and leave some tokens for the input. (One token is roughly 4 characters for normal English text)","defaultValue":2048,"type":"NUMBER"},"topP":{"displayName":"Top P","required":false,"description":"An alternative to sampling with temperature, called nucleus sampling, where the model considers the results of the tokens with top_p probability mass. So 0.1 means only the tokens comprising the top 10% probability mass are considered.","defaultValue":1,"type":"NUMBER"},"frequencyPenalty":{"displayName":"Frequency penalty","required":false,"description":"Number between -2.0 and 2.0. Positive values penalize new tokens based on their existing frequency in the text so far, decreasing the model's likelihood to repeat the same line verbatim.","defaultValue":0,"type":"NUMBER"},"presencePenalty":{"displayName":"Presence penalty","required":false,"description":"Number between -2.0 and 2.0. Positive values penalize new tokens based on whether they appear in the text so far, increasing the mode's likelihood to talk about new topics.","defaultValue":0.6,"type":"NUMBER"},"memoryKey":{"displayName":"Memory Key","description":"A memory key that will keep the chat history shared across runs and flows. Keep it empty to leave ChatGPT without memory of previous messages.","required":false,"type":"SHORT_TEXT"},"roles":{"displayName":"Roles","required":false,"description":"Array of roles to specify more accurate response","defaultValue":[{"role":"system","content":"You are a helpful assistant."}],"type":"JSON"}},"errorHandlingOptions":{"retryOnFailure":{"defaultValue":false},"continueOnFailure":{"defaultValue":false}}}}$ap$,
