        $ap${"ask-ai":{"name":"ask-ai","displayName":"Ask AI","description":"Ask Groq anything using fast language models.","requireAuth":true,"props":{"model":{"displayName":"Model","required":true,"description":"The model which will generate the completion.","refreshers":[],"defaultValue":"llama-3.1-70b-versatile","type":"DROPDOWN"},"prompt":{"displayName":"Question","required":true,"type":"LONG_TEXT"},"temperature":{"displayName":"Temperature","required":false,"description":"Controls randomness: Lowering results in less random completions. As the temperature approaches zero, the model will become deterministic and repetitive.","defaultValue":0.9,"type":"NUMBER"},"maxTokens":{"displayName":"Maximum Tokens","required":true,"description":"The maximum number of tokens to generate. The total length of input tokens and generated tokens is limited by the model's context length.","defaultValue":2048,"type":"NUMBER"},"topP":{"displayName":"Top P","required":false,"description":"An alternative to sampling with temperature, called nucleus sampling, where the model considers the results of the tokens with top_p probability mass. So 0.1 means only the tokens comprising the top 10% probability mass are considered.","defaultValue":1,"type":"NUMBER"},"frequencyPenalty":{"displayName":"Frequency penalty","required":false,"description":"Number between -2.0 and 2.0. Positive values penalize new tokens based on their existing frequency in the text so far, decreasing the model's likelihood to repeat the same line verbatim.","defaultValue":0,"type":"NUMBER"},"presencePenalty":{"displayName":"Presence penalty","required":false,"description":"Number between -2.0 and 2.0. Positive values penalize new tokens based on whether they appear in the text so far, increasing the model's likelihood to talk about new topics.","defaultValue":0.6,"type":"NUMBER"},"memoryKey":{"displayName":"Memory Key","description":"A memory key that will keep the chat history shared across runs and flows. Keep it empty to leave Groq without memory of previous messages.","required":false,"type":"SHORT_TEXT"},"roles":{"displayName":"Roles","required":false,"description":"Array of roles to specify more accurate response","defaultValue":[{"role":"system","content":"You are a helpful assistant."}],"type":"JSON"}},"errorHandlingOptions":{"retryOnFailure":{"defaultValue":false},"continueOnFailure":{"defaultValue":false}}},"transcribe-audio":{"name":"transcribe-audio","displayName":"Transcribe Audio","description":"Transcribes audio into text in the input language.","requireAuth":true,"props":{"file":{"displayName":"Audio File","required":true,"description":"The audio file to transcribe. Supported formats: flac, mp3, mp4, mpeg, mpga, m4a, ogg, wav, webm.","type":"FILE"},"model":{"displayName":"Model","required":true,"description":"The model to use for transcription.","refreshers":[],"defaultValue":"whisper-large-v3","type":"DROPDOWN"},"language":{"displayName":"Language","required":false,"description":"The language of the input audio in ISO-639-1 format (e.g., \"en\" for English). This will improve accuracy and latency.","type":"SHORT_TEXT"},"prompt":{"displayName":"Prompt","required":false,"description":"An optional text to guide the model's style or continue a previous audio segment. The prompt should match the audio language.","type":"LONG_TEXT"},"temperature":{"displayName":"Temperature","required":false,"description":"The sampling temperature, between 0 and 1. Higher values like 0.8 will make the output more random, while lower values like 0.2 will make it more focused and deterministic.","defaultValue":0,"type":"NUMBER"},"responseFormat":{"displayName":"Response Format","required":false,"description":"The format of the transcript output.","defaultValue":"json","options":{"disabled":false,"options":[{"label":"JSON","value":"json"},{"label":"Text","value":"text"},{"label":"Verbose JSON","value":"verbose_json"}]},"type":"STATIC_DROPDOWN"}},"errorHandlingOptions":{"retryOnFailure":{"defaultValue":false},"continueOnFailure":{"defaultValue":false}}},"translate-audio":{"name":"translate-audio","displayName":"Translate Audio","description":"Translates audio into English text.","requireAuth":true,"props":{"file":{"displayName":"Audio File","required":true,"description":"The audio file to translate. Supported formats: flac, mp3, mp4, mpeg, mpga, m4a, ogg, wav, webm.","type":"FILE"},"model":{"displayName":"Model","required":true,"description":"The model to use for translation.","refreshers":[],"defaultValue":"whisper-large-v3","type":"DROPDOWN"},"prompt":{"displayName":"Prompt","required":false,"description":"An optional text in English to guide the model's style or continue a previous audio segment.","type":"LONG_TEXT"},"temperature":{"displayName":"Temperature","required":false,"description":"The sampling temperature, between 0 and 1. Higher values like 0.8 will make the output more random, while lower values like 0.2 will make it more focused and deterministic.","defaultValue":0,"type":"NUMBER"},"responseFormat":{"displayName":"Response Format","required":false,"description":"The format of the translation output.","defaultValue":"json","options":{"disabled":false,"options":[{"label":"JSON","value":"json"},{"label":"Text","value":"text"},{"label":"Verbose JSON","value":"verbose_json"}]},"type":"STATIC_DROPDOWN"}},"errorHandlingOptions":{"retryOnFailure":{"defaultValue":false},"continueOnFailure":{"defaultValue":false}}},"custom_api_call":{"name":"custom_api_call","displayName":"Custom API Call","description":"Make a custom API call to a specific endpoint","requireAuth":true,"props":{"url":{"auth":{"description":"Enter your Groq API Key","displayName":"API Key","required":true,"type":"SECRET_TEXT"},"displayName":"","required":true,"refreshers":[],"type":"DYNAMIC"},"method":{"displayName":"Method","required":true,"options":{"options":[{"label":"GET","value":"GET"},{"label":"POST","value":"POST"},{"label":"PATCH","value":"PATCH"},{"label":"PUT","value":"PUT"},{"label":"DELETE","value":"DELETE"},{"label":"HEAD","value":"HEAD"}]},"type":"STATIC_DROPDOWN"},"headers":{"displayName":"Headers","description":"Authorization headers are injected automatically from your connection.","required":true,"type":"OBJECT"},"queryParams":{"displayName":"Query Parameters","required":true,"type":"OBJECT"},"body_type":{"displayName":"Body Type","required":false,"defaultValue":"none","options":{"disabled":false,"options":[{"label":"None","value":"none"},{"label":"JSON","value":"json"},{"label":"Form Data","value":"form_data"},{"label":"Raw","value":"raw"}]},"type":"STATIC_DROPDOWN"},"body":{"auth":{"description":"Enter your Groq API Key","displayName":"API Key","required":true,"type":"SECRET_TEXT"},"displayName":"Body","refreshers":["body_type"],"required":false,"type":"DYNAMIC"},"response_is_binary":{"displayName":"Response is Binary ?","description":"Enable for files like PDFs, images, etc.","required":false,"defaultValue":false,"type":"CHECKBOX"},"failsafe":{"displayName":"No Error on Failure","required":false,"type":"CHECKBOX"},"timeout":{"displayName":"Timeout (in seconds)","required":false,"type":"NUMBER"},"followRedirects":{"displayName":"Follow redirects","required":false,"defaultValue":false,"type":"CHECKBOX"}},"errorHandlingOptions":{"retryOnFailure":{"defaultValue":false},"continueOnFailure":{"defaultValue":false}}}}$ap$,
